begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,is_anonymous,raw_user_meta_data) values
('bc220000-0000-4000-8000-000000000001','presence-one@example.test',false,'{"character_name":"PresenceOne"}'),
('bc220000-0000-4000-8000-000000000002','presence-two@example.test',false,'{"character_name":"PresenceTwo"}'),
('bc220000-0000-4000-8000-000000000003','presence-anon@example.test',true,'{}');
insert into auth.sessions(id,user_id,created_at,updated_at) values
('bc220000-0000-4000-8000-000000000011','bc220000-0000-4000-8000-000000000001',now(),now()),
('bc220000-0000-4000-8000-000000000012','bc220000-0000-4000-8000-000000000002',now(),now());
create temp table fixture as select id,user_id from public.characters where user_id::text like 'bc220000-%';
create temp table saved(key text primary key,value timestamptz);
grant select on fixture to authenticated;
grant all on saved to authenticated;
select ok((select bool_and(relrowsecurity) from pg_class where oid in ('private.player_presence'::regclass,'private.character_actions'::regclass)),'Presence tables enable RLS');
set local role anon;
select throws_ok($$select public.record_player_presence(gen_random_uuid(),true)$$,'42501',null,'Anonymous presence writes denied');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"bc220000-0000-4000-8000-000000000001","role":"authenticated","session_id":"bc220000-0000-4000-8000-000000000011"}',true);
select throws_ok('select * from private.player_presence','42501',null,'Clients cannot read sessions');
select throws_ok('select * from private.character_actions','42501',null,'Clients cannot read action storage');
select throws_ok($$select private.record_character_action((select id from fixture limit 1))$$,'42501',null,'Clients cannot forge character action timestamps');
select is(public.get_character_status((select id from fixture where user_id='bc220000-0000-4000-8000-000000000001'))#>>'{presence,last_action_at}',null,'No invented historical activity');
select lives_ok($$select public.record_player_presence('bc220000-0000-4000-8000-000000000021',true,true)$$,'Live session reports a page action');
insert into saved select 'action',(public.get_character_status(id)#>>'{presence,last_action_at}')::timestamptz from fixture where user_id='bc220000-0000-4000-8000-000000000001';
select ok((select value between statement_timestamp()-interval '5 seconds' and statement_timestamp() from saved where key='action'),'Action uses server time');
select ok((public.get_character_status((select id from fixture where user_id='bc220000-0000-4000-8000-000000000001'))#>>'{presence,online_until}')::timestamptz>statement_timestamp(),'Active tab is online');
select public.record_player_presence('bc220000-0000-4000-8000-000000000021',true);
select is((public.get_character_status((select id from fixture where user_id='bc220000-0000-4000-8000-000000000001'))#>>'{presence,last_action_at}')::timestamptz,(select value from saved where key='action'),'Heartbeat does not change last action');
select public.record_player_presence('bc220000-0000-4000-8000-000000000022',false);
select ok((public.get_character_status((select id from fixture where user_id='bc220000-0000-4000-8000-000000000001'))#>>'{presence,online_until}')::timestamptz>statement_timestamp(),'Idle tab does not override active tab');
select public.record_player_presence('bc220000-0000-4000-8000-000000000021',false,false,true);
select is(public.get_character_status((select id from fixture where user_id='bc220000-0000-4000-8000-000000000001'))#>>'{presence,online_until}',null,'Closing active tab clears online status');
select ok((public.get_character_status((select id from fixture where user_id='bc220000-0000-4000-8000-000000000001'))#>>'{presence,connected_until}')::timestamptz>statement_timestamp(),'Remaining idle tab stays connected');
select public.record_player_presence('bc220000-0000-4000-8000-000000000022',true);
select ok((public.get_character_status((select id from fixture where user_id='bc220000-0000-4000-8000-000000000001'))#>>'{presence,online_until}')::timestamptz>statement_timestamp(),'Focus change bypasses write throttle');
select public.get_game_state();
select is((public.get_character_status((select id from fixture where user_id='bc220000-0000-4000-8000-000000000001'))#>>'{presence,last_action_at}')::timestamptz,(select value from saved where key='action'),'Automatic game refresh does not count as action');
select set_config('request.jwt.claims','{"sub":"bc220000-0000-4000-8000-000000000002","role":"authenticated","session_id":"bc220000-0000-4000-8000-000000000012"}',true);
select ok(public.get_character_status((select id from fixture where user_id='bc220000-0000-4000-8000-000000000001'))#>>'{presence,last_action_at}' is not null,'Other registered players see last action');
select is(public.get_character_status((select id from fixture where user_id='bc220000-0000-4000-8000-000000000002'))#>>'{presence,last_action_at}',null,'Viewing another profile never changes its owner');
select set_config('request.jwt.claims','{"sub":"bc220000-0000-4000-8000-000000000002","role":"authenticated","session_id":"bc220000-0000-4000-8000-000000000011"}',true);
select throws_ok($$select public.record_player_presence(gen_random_uuid(),true)$$,'42501','UNAUTHORIZED','Foreign session denied');
select set_config('request.jwt.claims','{"sub":"bc220000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.record_player_presence(gen_random_uuid(),true)$$,'42501','UNAUTHORIZED','Missing session denied');
reset role;
update private.player_presence set seen_at=statement_timestamp()-interval '1 day' where character_id in(select id from fixture);
set local role authenticated;
select ok((public.get_character_status((select id from fixture where user_id='bc220000-0000-4000-8000-000000000001'))#>>'{presence,connected_until}')::timestamptz<statement_timestamp(),'Lost connection expires without a close message');
select set_config('request.jwt.claims','{"sub":"bc220000-0000-4000-8000-000000000001","role":"authenticated","session_id":"bc220000-0000-4000-8000-000000000011"}',true);
select public.record_player_presence('bc220000-0000-4000-8000-000000000023',true);
reset role;
select is((select count(*) from private.player_presence where character_id in(select id from fixture)),1::bigint,'Expired tab rows are pruned on reconnect');
update public.characters set gold_coins=100 where id in(select id from fixture);
update private.character_actions set last_action_at=statement_timestamp()-interval '1 day' where character_id in(select id from fixture);
set local role authenticated;
select public.transfer_gold('deposit',1,'bc220000-0000-4000-8000-000000000030');
insert into saved select 'bank',(public.get_character_status(id)#>>'{presence,last_action_at}')::timestamptz from fixture where user_id='bc220000-0000-4000-8000-000000000001';
select ok((select value>statement_timestamp()-interval '5 seconds' from saved where key='bank'),'Committed game action resets last action');
select public.transfer_gold('deposit',1,'bc220000-0000-4000-8000-000000000030');
select is((public.get_character_status((select id from fixture where user_id='bc220000-0000-4000-8000-000000000001'))#>>'{presence,last_action_at}')::timestamptz,(select value from saved where key='bank'),'Receipt replay is not a new action');
select throws_ok($$select public.transfer_gold('deposit',-1,gen_random_uuid())$$,null,null,'Rejected game action');
select is((public.get_character_status((select id from fixture where user_id='bc220000-0000-4000-8000-000000000001'))#>>'{presence,last_action_at}')::timestamptz,(select value from saved where key='bank'),'Rejected action preserves last action');
reset role;
update auth.sessions set not_after=statement_timestamp()-interval '1 second' where id='bc220000-0000-4000-8000-000000000011';
set local role authenticated;
select throws_ok($$select public.record_player_presence(gen_random_uuid(),true)$$,'42501','UNAUTHORIZED','Expired session denied');
select is(public.get_character_status((select id from fixture where user_id='bc220000-0000-4000-8000-000000000001'))#>>'{presence,connected_until}',null,'Expired Auth session cannot remain online');
reset role;
delete from auth.sessions where id='bc220000-0000-4000-8000-000000000011';
select is((select count(*) from private.player_presence where character_id in(select id from fixture)),0::bigint,'Sign-out removes session presence');
set local role authenticated;
select throws_ok($$select public.record_player_presence(gen_random_uuid(),true)$$,'42501','UNAUTHORIZED','Revoked session denied');
select set_config('request.jwt.claims','{"sub":"bc220000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select is(private.get_player_presence((select id from fixture limit 1)),null::jsonb,'Anonymous Auth users cannot read presence');
reset role;
delete from auth.users where id='bc220000-0000-4000-8000-000000000001';
select is((select count(*) from private.character_actions where character_id in(select id from fixture)),0::bigint,'Deleting account removes action timestamps');
select * from finish();
rollback;
